def solve(tokens):
    """Evaluate Reverse Polish Notation expression list and return integer result.
    Supports +, -, *, / where division truncates toward zero."""
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                stack.append(a + b)
            elif tok == '-':
                stack.append(a - b)
            elif tok == '*':
                stack.append(a * b)
            else:  # division
                # Truncate toward zero
                stack.append(int(a / b))
        else:
            stack.append(int(tok))
    return stack[-1] if stack else 0

def solve(a: str, b: str) -> int:
    n, m = len(a), len(b)
    # DP with two rows for space efficiency
    prev = list(range(m + 1))
    for i in range(1, n + 1):
        cur = [i] + [0] * m
        for j in range(1, m + 1):
            if a[i-1] == b[j-1]:
                cost = 0
            else:
                cost = 1
            cur[j] = min(prev[j] + 1,        # delete
                         cur[j-1] + 1,      # insert
                         prev[j-1] + cost)  # substitute
        prev = cur
    return prev[m]

