def brute(nums):
    n=len(nums)
    best=0
    from itertools import combinations
    for r in range(1,n+1):
        for idxs in combinations(range(n),r):
            seq=[nums[i] for i in idxs]
            if all(seq[i]<seq[i+1] for i in range(len(seq)-1)):
                best=max(best,r)
    return best

