    fields = []
    i = 0
    n = len(line)
    # Special case: empty line returns ['']
    if n == 0:
        return ['']
    while i < n:
        if line[i] == '"':
            # start quoted field
            i += 1
            start = i
            field = ''
            while i < n:
                if line[i] == '"':
                    # could be end or escaped quote
                    if i + 1 < n and line[i+1] == '"':
                        # escaped quote, add one quote and skip both
                        field += '"'
                        i += 2
                        continue
                    else:
                        # end of quoted field
                        i += 1
                        break
                else:
                    field += line[i]
                    i += 1
            # after quoted field, expect comma or end
            fields.append(field)
            if i < n and line[i] == ',':
                i += 1  # skip comma
        else:
            # unquoted field
            start = i
            while i < n and line[i] != ',':
                i += 1
            fields.append(line[start:i])
            if i < n and line[i] == ',':
                i += 1
