def solve(path):
    """Simplify an absolute Unix path.
    Resolve '.' and '..', collapse multiple slashes, and remove any trailing slash.
    The root is '/' and stays '/' if the result would be empty.
    """
    # Assumes path is a string representing an absolute path.
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            # Skip empty components caused by leading, trailing, or multiple slashes, and current directory.
            continue
        if part == '..':
            # Go up one directory if possible.
            if stack:
                stack.pop()
            # If already at root, stay there.
        else:
            # Regular directory name (may contain any characters except '/').
            stack.append(part)
    # Construct the canonical path.
    return '/' + '/'.join(stack)

