    Returns a flat list preserving depth‑first order.
    Non‑integer elements (including bool) are ignored.
    """
    result = []
    def helper(item):
        # If item is an int (but not bool), record it
        if isinstance(item, int) and not isinstance(item, bool):
            result.append(item)
