def solve(matrix):
    """Return the determinant of a square integer matrix.
    Uses exact arithmetic with Fractions to avoid rounding errors and
    handles zero pivots by row swapping (changing sign). Works for any
    size that fits in memory.
    """
    from fractions import Fraction
    # Empty matrix – define determinant as 1 (empty product)
    if not matrix:
        return 1
    n = len(matrix)
    for row in matrix:
        if len(row) != n:
            raise ValueError("Matrix must be square")
    # Convert to Fraction matrix
    A = [[Fraction(val) for val in row] for row in matrix]
    det_sign = 1
    for i in range(n):
        # Find pivot
        pivot_row = None
        for r in range(i, n):
            if A[r][i] != 0:
                pivot_row = r
                break
        if pivot_row is None:
            return 0
        if pivot_row != i:
            A[i], A[pivot_row] = A[pivot_row], A[i]
            det_sign *= -1
        pivot = A[i][i]
        # Eliminate rows below
        for r in range(i + 1, n):
            factor = A[r][i] / pivot
            for c in range(i, n):
                A[r][c] -= factor * A[i][c]
    # Determinant is product of diagonal entries times sign
    det = det_sign
    for i in range(n):
        det *= A[i][i]
    # det should be integer; convert
    if det.denominator != 1:
        # Should not happen for integer matrix, but round just in case
        return int(det.numerator // det.denominator)
    return det.numerator

