def solve(matrix):
    """Return the determinant of an integer square matrix.
    Uses the Bareiss algorithm for exact integer arithmetic.
    An empty matrix has determinant 1.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Copy matrix to avoid mutating input
    A = [list(map(int, row)) for row in matrix]
    if n == 1:
        return A[0][0]
    sign = 1
    for k in range(n - 1):
        # Pivot: if zero, find a non-zero row to swap
        if A[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            A[k], A[swap_row] = A[swap_row], A[k]
            sign = -sign
        pivot = A[k][k]
        prev_pivot = A[k - 1][k - 1] if k > 0 else 1
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // prev_pivot
            A[i][k] = 0
    return sign * A[n - 1][n - 1]

