{"task_id": "T25", "code": "def solve(matrix):
    """Compute the determinant of an integer square matrix.
    Uses exact rational Gaussian elimination (Fractions) to avoid overflow and
    handle zero pivots correctly. An empty matrix has determinant 1.
    """
    from fractions import Fraction
    if not matrix:
        return 1
    n = len(matrix)
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Convert to Fractions
    A = [[Fraction(int(val)) for val in row] for row in matrix]
    det = Fraction(1)
    sign = 1
    for i in range(n):
        # Find pivot row
        pivot_row = None
        for r in range(i, n):
            if A[r][i] != 0:
                pivot_row = r
                break
        if pivot_row is None:
            return 0
        if pivot_row != i:
            A[i], A[pivot_row] = A[pivot_row], A[i]
            sign = -sign
        pivot = A[i][i]
        det *= pivot
        # Eliminate rows below
        for r in range(i+1, n):
            factor = A[r][i] / pivot
            for c in range(i, n):
                A[r][c] -= factor * A[i][c]
    # Determinant is sign * product of pivots (det)
    result = sign * det
    # result should be integer
    return int(result)
"}

