def solve(meetings):
    if not meetings:
        return 0
    meetings = sorted(meetings, key=lambda x: (x[1], x[0]))
    cnt = 0
    last_end = -10**18
    for s,e in meetings:
        if s >= last_end:
            cnt+=1
            last_end = e
    return cnt

def brute(meetings):
    # try all subsets
    best=0
    n=len(meetings)
    from itertools import combinations
    for r in range(1,n+1):
        for combo in combinations(meetings,r):
            # check no overlap
            ok=True
            sorted_combo=sorted(combo,key=lambda x:x[0])
            for i in range(len(sorted_combo)-1):
                if sorted_combo[i][1] > sorted_combo[i+1][0]:
                    ok=False;break
            if ok:
                best=max(best,r)
    return best

import random, sys
for _ in range(2000):
    m=random.randint(0,8)
    meetings=[]
    for __ in range(m):
        a=random.randint(0,20)
        b=random.randint(a, a+5)
        meetings.append([a,b])
    if solve(meetings)!=brute(meetings):
        print('Mismatch', meetings, solve(meetings), brute(meetings))
