def solve(matrix):
    """Return determinant of an integer square matrix using the Bareiss algorithm.
    Returns 1 for an empty matrix.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # Verify square matrix
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Copy matrix to avoid mutating input
    a = [list(row) for row in matrix]
    sign = 1
    prev = 1
    for k in range(n - 1):
        # Ensure pivot is non-zero, swap rows if needed
        if a[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            a[k], a[swap_row] = a[swap_row], a[k]
            sign = -sign
        pivot = a[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j]) // prev
            a[i][k] = 0
        prev = pivot
    return sign * a[n - 1][n - 1]

